  (* [comment removed for export] *)
  Lemma ann_L1b : forall (M : word -> option byte) regs, cellA M 0x164518 8 0x16d7b8 -> cellA M 0x16d7b8 8 0x7fff8000 ->
    (e mod 8 <> 0 -> exists sv, cellA M (0x7fff8000 + e / 8) 1 sv /\ (sv = 252 \/ (1 <= sv <= 7 /\ sv <= e mod 8))) ->
    o <> m -> getr regs 9 = Z_to_bv 64 b -> getr regs 18 = Z_to_bv 64 m -> getr regs 19 = Z_to_bv 64 o -> getr regs 20 = Z_to_bv 64 e ->
    exists regs', msteps ASEGS (mkst regs (0x84a10 : word) M rom) (mkst regs' (0x84a1c : word) M rom)
