  (* [comment removed for export] *)
  Definition ann_lo : Z := if o <? m then o / 8 else (m + 7) / 8.
  Definition ann_hi : Z := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S10!1,6|30;-^0RN$~R+^0+0!2'^;/o;/m;2!2'@/m;0!2'@!2'^K/o;!1,6|23;0").
